// Cloudflare entry: OpenNext's generated worker, plus the isolation headers.
//
// WebContainer only boots on a cross-origin isolated page. next.config.ts and
// middleware.ts both set COOP/COEP for /room, but neither reached the browser
// through OpenNext, so the IDE always failed with "Failed to start
// WebContainer". Setting them here, on the final response, does not depend on
// how OpenNext applies Next's header rules.

// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export default {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    const response: Response = await handler.fetch(request, env, ctx);

    const { pathname } = new URL(request.url);
    if (!pathname.startsWith("/room")) return response;

    const isolated = new Response(response.body, response);
    isolated.headers.set("Cross-Origin-Opener-Policy", "same-origin");
    isolated.headers.set("Cross-Origin-Embedder-Policy", "credentialless");
    return isolated;
  },
};

// @ts-expect-error generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
